(window.AtlasPacks = window.AtlasPacks || {})["ja"] = {"strings":{"{n} billion":"{n}十億","{n} million":"{n}百万","{n} thousand":"{n}千","Flag of {name}":"{name}の国旗","Captain Skye":"スカイ機長","Next":"つぎへ","Whole world":"世界ぜんぶ","Which country has this flag?":"この国旗はどこの国？","Which flag belongs to {name}?":"{name}の国旗はどれ？","What is the capital of {name}?":"{name}の首都はどこ？","{city} is the capital of…":"{city}はどこの国の首都？","Find {name}":"{name}をさがそう","It is tiny: look for its dot!":"とても小さい国だよ。点をさがしてね！","Tap it on the globe.":"地球ぎの上でタップしてね。","Where is {city}?":"{city}はどこ？","Tap the country it is the capital of.":"この町が首都になっている国をタップしてね。","{name} is famous for…":"{name}で有名なものは…","Which country is a neighbour of {name}?":"{name}のおとなりの国はどれ？","Which language do many people speak in {name}?":"{name}で多くの人が話していることばはどれ？","Which continent is {name} in?":"{name}はどの大陸にある？","Does {name} touch the sea?":"{name}は海に面している？","Yes, it has a coast":"うん、海岸があるよ","No, it is landlocked":"ううん、海がない国だよ","Which has more people?":"人口が多いのはどっち？","Fly to the country with this flag":"この国旗の国へ飛ぼう","Fly to the country famous for {thing}":"{thing}で有名な国へ飛ぼう","Fly to the country whose capital is {city}":"首都が{city}の国へ飛ぼう","Fly to the country next to {a} and {b}":"{a}と{b}のとなりの国へ飛ぼう","{mode} · {n} right":"{mode} · {n}問せいかい","Quiz: {name}":"クイズ：{name}","{mode} · {i} of {n}":"{mode} · {i}/{n}","Flag {n}":"国旗 {n}","Show me":"おしえて","{name} lights up on your map!":"きみの地図で{name}が光ったよ！","Right! {n} in a row!":"せいかい！{n}問れんぞく！","Right!":"せいかい！","Not quite. Here is the answer.":"おしい！こたえはこれだよ。","Not quite: that is the flag of {name}.":"おしい！それは{name}の国旗だよ。","Not quite: {city} is the capital of {name}.":"おしい！{city}は{name}の首都だよ。","Not quite: that was {name}.":"おしい！それは{name}だったよ。","About {name}":"{name}について","Finish":"おわる","{name} is lit!":"{name}が光った！","You lit up all of {region}! New badge in your passport.":"{region}をぜんぶ光らせたね！パスポートに新しいバッジだよ。","New plane paint in your passport!":"パスポートに新しい飛行機の色がふえたよ！","That is {name}.":"それは{name}だよ。","{place} is about {km} km to the {dir}.":"{place}は{dir}へ約{km} kmのところだよ。","Here it is: {name}.":"ここだよ：{name}。","You got {a} of {b} right!":"{b}問中{a}問せいかい！","{n} in 60 seconds!":"60びょうで{n}問！","Expedition done: {a} of {b}":"たんけん完了：{b}問中{a}問","{a} of {b} right!":"{b}問中{a}問せいかい！","{n} of 3 to light it up":"光らせるまで {n}/3","Lit!":"光った！","Capital":"首都","People":"人口","Languages":"ことば","Famous for":"有名なもの","Neighbours":"となりの国","None: only the sea!":"なし：まわりは海だけ！","Did you know?":"知ってた？","Read it to me":"読んで","Close":"とじる","Quiz me":"クイズ","Tap any country on the globe to open its file.":"地球ぎの国をタップすると、その国のファイルがひらくよ。","{n} lit":"{n}こ光った","Your passport":"きみのパスポート","{n} of {all} countries lit up.":"{all}か国中{n}か国が光ったよ。","Get a country right 3 times to light it up.":"1つの国を3回せいかいすると、その国が光るよ。","Best speed round: {n}":"スピード戦のさいこう記録：{n}","Expedition streak: {n} days":"たんけんれんぞく：{n}日","Plane paint":"飛行機の色","Stamps":"スタンプ","Continents":"大陸","Done":"できた","Atlas Quest settings":"Atlas Quest のせってい","Start over":"さいしょから","Clears your lit countries, stamps and paint":"光った国、スタンプ、色がぜんぶ消えるよ","Start over?":"さいしょからやりなおす？","Your map goes back to grey. This cannot be undone.":"地図がはい色にもどるよ。もとにはもどせないよ。","Keep my map":"地図をのこす","Yes, start over":"うん、やりなおす","A fresh grey map. Off you go!":"まっさらなはい色の地図だよ。さあ、出発！","Sound and more":"音など","{n} of {all} countries lit up":"{all}か国中{n}か国が光った","Where to, pilot?":"パイロットさん、どこへ行く？","{n} countries lit up. Keep going!":"{n}か国が光ったよ。そのちょうし！","Light up the world: get a country right 3 times to colour it in.":"世界を光らせよう！1つの国を3回せいかいすると、色がつくよ。","Easy: famous countries":"かんたん：有名な国","Explorer: every country":"たんけん家：すべての国","Done today! Streak: {n}":"今日はクリア！れんぞく：{n}","Best: {n}":"さいこう：{n}","Drag to spin the globe, pinch to zoom, tap a country to read its file.":"ドラッグで地球ぎを回して、ピンチでズーム。国をタップするとファイルが読めるよ。","Fly round the world and light up every country!":"世界中を飛んで、すべての国を光らせよう！","Welcome aboard, pilot! I am Captain Skye. The world map has gone all grey, and we need a sharp-eyed explorer to colour it back in.":"ようこそ、パイロットさん！ぼくはスカイ機長だよ。世界地図がぜんぶはい色になっちゃったんだ。目のいいたんけん家に、色をとりもどしてほしいんだ。","Let's fly!":"飛びたとう！","Title screen":"タイトル画面","Settings":"せってい","Back":"もどる","Africa":"アフリカ","Asia":"アジア","Europe":"ヨーロッパ","North America":"北アメリカ","South America":"南アメリカ","Oceania":"オセアニア","Find it":"さがそう","Tap countries on the globe":"地球ぎの国をタップ","Flag match":"国旗あわせ","Flags and their countries":"国旗とその国","Capital hop":"首都めぐり","Capital cities":"国の首都","Daily expedition":"毎日のたんけん","A new route every day":"毎日ちがうルート","Speed round":"スピード戦","60 seconds, go!":"60びょう、スタート！","Country files":"国のファイル","Sky blue":"そら色","Coral red":"コーラルレッド","Mint green":"ミントグリーン","Grape purple":"ぶどう色","Sunny yellow":"おひさま黄色","Peach":"もも色","Cocoa":"ココア色","Snow white":"雪の白","north":"北","north-east":"北東","east":"東","south-east":"南東","south":"南","south-west":"南西","west":"西","north-west":"北西","Dari":"ダリー語","Pashto":"パシュトー語","Portuguese":"ポルトガル語","Umbundu":"ウンブンドゥ語","Kimbundu":"キンブンドゥ語","Albanian":"アルバニア語","Catalan":"カタルーニャ語","Spanish":"スペイン語","Arabic":"アラビア語","English":"英語","Armenian":"アルメニア語","German":"ドイツ語","Azerbaijani":"アゼルバイジャン語","Russian":"ロシア語","Kirundi":"キルンディ語","French":"フランス語","Dutch":"オランダ語","Fon":"フォン語","Yoruba":"ヨルバ語","Moore":"モシ語","Dyula":"ジュラ語","Bengali":"ベンガル語","Bulgarian":"ブルガリア語","Bosnian":"ボスニア語","Croatian":"クロアチア語","Serbian":"セルビア語","Belarusian":"ベラルーシ語","Belizean Creole":"ベリーズ・クレオール語","Quechua":"ケチュア語","Aymara":"アイマラ語","Malay":"マレー語","Dzongkha":"ゾンカ語","Tswana":"ツワナ語","Sango":"サンゴ語","Italian":"イタリア語","Chinese":"中国語","Baoule":"バウレ語","Lingala":"リンガラ語","Swahili":"スワヒリ語","Kituba":"キトゥバ語","Comorian":"コモロ語","Cape Verdean Creole":"カーボベルデ・クレオール語","Greek":"ギリシャ語","Turkish":"トルコ語","Czech":"チェコ語","Somali":"ソマリ語","Danish":"デンマーク語","Berber":"ベルベル語","Tigrinya":"ティグリニャ語","Estonian":"エストニア語","Amharic":"アムハラ語","Oromo":"オロモ語","Finnish":"フィンランド語","Swedish":"スウェーデン語","Fijian":"フィジー語","Fiji Hindi":"フィジー・ヒンディー語","Chuukese":"チューク語","Pohnpeian":"ポンペイ語","Fang":"ファン語","Georgian":"ジョージア語","Twi":"トウィ語","Ewe":"エウェ語","Fula":"フラ語","Maninka":"マニンカ語","Mandinka":"マンディンカ語","Wolof":"ウォロフ語","Kriol":"クリオール語","Haitian Creole":"ハイチ・クレオール語","Hungarian":"ハンガリー語","Indonesian":"インドネシア語","Hindi":"ヒンディー語","Irish":"アイルランド語","Persian":"ペルシャ語","Kurdish":"クルド語","Icelandic":"アイスランド語","Hebrew":"ヘブライ語","Jamaican Patois":"ジャマイカ・パトワ語","Japanese":"日本語","Kazakh":"カザフ語","Kyrgyz":"キルギス語","Khmer":"クメール語","Gilbertese":"キリバス語","Korean":"韓国語","Lao":"ラオ語","Sinhala":"シンハラ語","Tamil":"タミル語","Sotho":"ソト語","Lithuanian":"リトアニア語","Luxembourgish":"ルクセンブルク語","Latvian":"ラトビア語","Romanian":"ルーマニア語","Malagasy":"マダガスカル語","Dhivehi":"ディベヒ語","Marshallese":"マーシャル語","Macedonian":"マケドニア語","Bambara":"バンバラ語","Maltese":"マルタ語","Burmese":"ビルマ語","Montenegrin":"モンテネグロ語","Mongolian":"モンゴル語","Makhuwa":"マクア語","Tsonga":"ツォンガ語","Mauritian Creole":"モーリシャス・クレオール語","Chewa":"チェワ語","Oshiwambo":"オシワンボ語","Afrikaans":"アフリカーンス語","Hausa":"ハウサ語","Zarma":"ザルマ語","Norwegian":"ノルウェー語","Sami":"サーミ語","Nepali":"ネパール語","Nauruan":"ナウル語","Māori":"マオリ語","Urdu":"ウルドゥー語","Punjabi":"パンジャブ語","Filipino":"フィリピノ語","Palauan":"パラオ語","Tok Pisin":"トク・ピシン語","Hiri Motu":"ヒリモツ語","Polish":"ポーランド語","Guaraní":"グアラニー語","Kinyarwanda":"キニヤルワンダ語","Pijin":"ソロモン・ピジン語","Krio":"クリオ語","Dinka":"ディンカ語","Forro":"フォロ語","Sranan Tongo":"スラナン・トンゴ語","Slovak":"スロバキア語","Slovene":"スロベニア語","Swazi":"スワジ語","Seychellois Creole":"セーシェル・クレオール語","Kabiye":"カビエ語","Thai":"タイ語","Tajik":"タジク語","Turkmen":"トルクメン語","Tetum":"テトゥン語","Tongan":"トンガ語","Tuvaluan":"ツバル語","Luganda":"ルガンダ語","Ukrainian":"ウクライナ語","Uzbek":"ウズベク語","Latin":"ラテン語","Vietnamese":"ベトナム語","Bislama":"ビスラマ語","Samoan":"サモア語","Zulu":"ズールー語","Xhosa":"コサ語","Bemba":"ベンバ語","Nyanja":"ニャンジャ語","Shona":"ショナ語","Ndebele":"ンデベレ語","name.AF":"アフガニスタン","cap.AF":"カブール","fam.AF":"青いラピスラズリの石","fact.AF":"アフガニスタンのバンデ・アミール湖はあざやかな青色。自然にできたミネラルのかべが、石のダムのように水をせき止めているんだよ。","name.AO":"アンゴラ","cap.AO":"ルアンダ","fam.AO":"大きなジャイアントセーブルアンテロープ","fact.AO":"カランドゥーラの滝はアフリカでもとくに大きな滝の1つ。高さは100メートル以上、はばは約400メートルもあるよ。","name.AL":"アルバニア","cap.AL":"ティラナ","fam.AL":"「青い目」とよばれるわき水","fact.AL":"アルバニアでは、首をたてにふると「いいえ」、よこにふると「はい」という人が多いんだ。ほかの多くの国とは反対だね！","name.AD":"アンドラ","cap.AD":"アンドララベリャ","fam.AD":"2人の共同君主","fact.AD":"アンドラには空港も鉄道もないよ。だから、おとずれる人はみんな、高いピレネー山脈をこえて道路でやってくるんだ。","name.AE":"アラブ首長国連邦","cap.AE":"アブダビ","fam.AE":"高層ビルのブルジュ・ハリファ","fact.AE":"暑いさばくの国なのに、本物の雪がふる大きな室内スキー場があって、ペンギンまでいるんだよ！","name.AR":"アルゼンチン","cap.AR":"ブエノスアイレス","fam.AR":"ペリト・モレノ氷河","fact.AR":"これまで見つかった中で最大級の恐竜の化石が、アルゼンチン南部のパタゴニアでほり出されたよ。長さ30メートル以上の草食恐竜なんだ。","name.AM":"アルメニア","cap.AM":"エレバン","fam.AM":"アンズとアララト山","fact.AM":"世界でいちばん古い革のくつが、アルメニアのどうくつで見つかったよ。約5,500年前のもので、中には草がつめてあったんだ！","name.AG":"アンティグア・バーブーダ","cap.AG":"セントジョンズ","fam.AG":"365このすなはま","fact.AG":"バーブーダ島には、世界最大級のグンカンドリのむれがいるよ。オスはのどの赤いふくろを風船みたいに大きくふくらませるんだ。","name.AU":"オーストラリア","cap.AU":"キャンベラ","fam.AU":"カンガルー","fact.AU":"グレートバリアリーフは、生き物がつくったものとしては地球でいちばん大きいんだ。宇宙からも見えるんだって！","name.AT":"オーストリア","cap.AT":"ウィーン","fam.AT":"モーツァルトの音楽","fact.AT":"オーストリアのシェーンブルン動物園は1752年にできたよ。今も開いている動物園の中では、世界でいちばん古いんだ。","name.AZ":"アゼルバイジャン","cap.AZ":"バクー","fam.AZ":"もえつづける丘ヤナル・ダグ","fact.AZ":"アゼルバイジャンには、地球の泥火山のおよそ半分、何百もの泥火山があるよ。つめたいドロドロのどろを、ボコボコ、ゲップみたいにふき出すんだ。","name.BI":"ブルンジ","cap.BI":"ギテガ","fam.BI":"有名な王室のたいこうち","fact.BI":"王室のたいこうちは、おどりながら大きなたいこをたたくよ。入場するときは、重いたいこを頭にのせて歩いてくるんだ！","name.BE":"ベルギー","cap.BE":"ブリュッセル","fam.BE":"ワッフルとチョコレート","fact.BE":"スマーフも、まんがのヒーローのタンタンも、ベルギーで生まれたよ。ベルギーはまんがが大すきな国なんだ！","name.BJ":"ベナン","cap.BJ":"コトヌー","fam.BJ":"湖の上の村ガンビエ","fact.BJ":"正式な首都はポルトノボだけど、政府の仕事はおもにコトヌーでしているよ。ガンビエでは、湖の上に立つ高床の家で人がくらしているんだ！","name.BF":"ブルキナファソ","cap.BF":"ワガドゥグー","fam.BF":"映画祭のフェスパコ","fact.BF":"2年に1回、アフリカ最大の映画祭フェスパコがひらかれるよ。アフリカ中から映画をつくる人があつまって、作品を見せあうんだ。","name.BD":"バングラデシュ","cap.BD":"ダッカ","fam.BD":"コックスバザールの長いすなはま","fact.BD":"バングラデシュには、世界最大のマングローブの森シュンドルボンがあるよ。そこのトラは泳ぎがとくいで、広い川もわたっちゃうんだ。","name.BG":"ブルガリア","cap.BG":"ソフィア","fam.BG":"バラの油とヨーグルト","fact.BG":"ブルガリアではたくさんのバラをそだてていて、世界のバラの油の大きなわりあいをつくっているよ。世界中の香水につかわれているんだ。","name.BH":"バーレーン","cap.BH":"マナーマ","fam.BH":"さばくの「生命の木」","fact.BH":"バーレーンは30以上の島でできた国だよ。いちばん大きな島は、長さ25キロメートルの橋でサウジアラビアとつながっているんだ。","name.BS":"バハマ","cap.BS":"ナッソー","fam.BS":"泳ぐブタ","fact.BS":"バハマは約700の島と、「ケイ」とよばれる2,000以上の小さな島でできているよ。すきとおったターコイズ色の海に広がっているんだ。","name.BA":"ボスニア・ヘルツェゴビナ","cap.BA":"サラエボ","fam.BA":"モスタルの古い橋","fact.BA":"毎年夏になると、ゆうかんなダイバーがモスタルの古い橋から、20メートル以上下の川へとびこむんだ！","name.BY":"ベラルーシ","cap.BY":"ミンスク","fam.BY":"ジャガイモのパンケーキ「ドラニキ」","fact.BY":"ベラルーシの古いベロヴェーシの森には、ヨーロッパでいちばん重い陸の動物、ヨーロッパバイソンがくらしているよ。","name.BZ":"ベリーズ","cap.BZ":"ベルモパン","fam.BZ":"グレート・ブルーホール","fact.BZ":"ベリーズには、世界ではじめてのジャガーの保護区があるよ。大きなもようのネコを守るためにつくられた熱帯雨林なんだ。","name.BO":"ボリビア","cap.BO":"ラパス","fam.BO":"ウユニ塩原","fact.BO":"ボリビアには首都が2つあるよ。政府があるラパスと、スクレなんだ。ラパスは海面から約3,600メートルも高いところにあるよ！","name.BR":"ブラジル","cap.BR":"ブラジリア","fam.BR":"キリスト像","fact.BR":"ブラジルはサッカーの男子ワールドカップで5回も優勝しているよ。これは世界のどの国よりも多いんだ。","name.BB":"バルバドス","cap.BB":"ブリッジタウン","fam.BB":"トビウオ","fact.BB":"グレープフルーツは1700年代にバルバドスで見つかったよ。ブンタンとオレンジが自然にまざってできたんだ。","name.BN":"ブルネイ","cap.BN":"バンダルスリブガワン","fam.BN":"水上の村カンポン・アイール","fact.BN":"ブルネイのカンポン・アイールは、川の上に柱を立ててつくった大きな村だよ。水の上に学校もお店も消防署もあるんだ。","name.BT":"ブータン","cap.BT":"ティンプー","fam.BT":"タイガーズ・ネスト（タクツァン僧院）","fact.BT":"ブータンでは、お金だけでなく、国民がどれだけしあわせかを「国民総幸福量」という数ではかっているよ。","name.BW":"ボツワナ","cap.BW":"ハボローネ","fam.BW":"オカバンゴ・デルタ","fact.BW":"オカバンゴ川は海までとどかない川なんだ。カラハリさばくのまん中で広がって、大きな緑のデルタになるよ。","name.CF":"中央アフリカ共和国","cap.CF":"バンギ","fam.CF":"ザンガ・バイのゾウ","fact.CF":"ザンガ・サンガでは、何百頭ものマルミミゾウが「バイ」という大きなどろの広場にあつまって、ミネラルたっぷりの水を飲むんだ。","name.CA":"カナダ","cap.CA":"オタワ","fam.CA":"メープルシロップ","fact.CA":"カナダの海岸線は世界一長くて、24万キロメートル以上あるよ。1日20キロメートルずつ歩いても、30年以上かかるんだ！","name.CH":"スイス","cap.CH":"ベルン","fam.CH":"チョコレート、チーズ、うで時計","fact.CH":"スイスには国のことばが4つあるよ。ドイツ語、フランス語、イタリア語、ロマンシュ語なんだ。湖も1,500以上あるよ。","name.CL":"チリ","cap.CL":"サンティアゴ","fam.CL":"イースター島のモアイ像","fact.CL":"チリはとっても細長い国だよ。北から南まで約4,300キロメートルもあるのに、はばは平均で約175キロメートルしかないんだ。","name.CN":"中国","cap.CN":"北京","fam.CN":"ジャイアントパンダ","fact.CN":"中国はアメリカ本土と同じくらい東西に広いのに、国全体で時間帯を1つしかつかっていないんだ。","name.CI":"コートジボワール","cap.CI":"ヤムスクロ","fam.CI":"カカオの生産が世界一なこと","fact.CI":"この国はカカオを世界でいちばんたくさんつくっているよ。きみが食べるチョコレートも、ここでそだったカカオ豆からできているかも！","name.CM":"カメルーン","cap.CM":"ヤウンデ","fam.CM":"「小さなアフリカ」とよばれること","fact.CM":"1つの国にすなはま、さばく、山、熱帯雨林、サバンナがぜんぶあるから、「小さなアフリカ」とよばれているんだ。","name.CD":"コンゴ民主共和国","cap.CD":"キンシャサ","fam.CD":"ボノボとオカピ","fact.CD":"野生のボノボとオカピは、この国にしかいないよ。オカピはシマウマみたいなしまもようだけど、じつはキリンのなかまなんだ！","name.CG":"コンゴ共和国","cap.CG":"ブラザビル","fam.CG":"オザラ・コクアのゴリラ","fact.CG":"国の半分以上が熱帯雨林におおわれていて、ニシローランドゴリラやマルミミゾウ、チンパンジーがすんでいるよ。","name.CO":"コロンビア","cap.CO":"ボゴタ","fam.CO":"カーニョ・クリスタレス川","fact.CO":"コロンビアには、世界のどの国よりも多い1,900種以上の鳥がいるよ。小さなハチドリから大きなコンドルまでいるんだ。","name.KM":"コモロ","cap.KM":"モロニ","fam.KM":"シーラカンスとイランイラン","fact.KM":"恐竜といっしょにいなくなったと思われていた魚のシーラカンスが、今もこの島のまわりの深い海で泳いでいるんだ。","name.CV":"カーボベルデ","cap.CV":"プライア","fam.CV":"歌手のセザリア・エヴォラ","fact.CV":"フォゴ島には今も活動している大きな火山があって、人びとはその大きな火口の中でブドウやコーヒーをそだてているよ。","name.CR":"コスタリカ","cap.CR":"サンホセ","fam.CR":"ナマケモノとアレナル火山","fact.CR":"コスタリカは地球の陸地のほんの少ししかないのに、世界の植物と動物の種類の約5%がすんでいるんだ。","name.CU":"キューバ","cap.CU":"ハバナ","fam.CU":"1950年代のクラシックカー","fact.CU":"マメハチドリはキューバにしかいない、世界でいちばん小さな鳥だよ。長さはたった5センチメートルくらいなんだ。","name.CY":"キプロス","cap.CY":"ニコシア","fam.CY":"ハルーミチーズ","fact.CY":"キプロスには、ムフロンという野生のヒツジがいるよ。島の山の森にすんでいて、コインにもえがかれているんだ。","name.CZ":"チェコ","cap.CZ":"プラハ","fam.CZ":"カレル橋","fact.CZ":"「ロボット」ということばは、チェコの作家カレル・チャペックが1920年の劇ではじめてつかったよ。チェコ語の「つらい仕事」ということばからきているんだ。","name.DE":"ドイツ","cap.DE":"ベルリン","fam.DE":"おとぎ話のようなノイシュバンシュタイン城","fact.DE":"ドイツにはパンが3,000種類以上あるといわれているよ。プレッツェルやライ麦パンで有名なんだ。","name.DJ":"ジブチ","cap.DJ":"ジブチ","fam.DJ":"アッサル湖の塩の岸","fact.DJ":"アッサル湖は海面より約155メートルひくい、アフリカでいちばんひくい場所だよ。水は死海よりもしょっぱいんだ。","name.DM":"ドミニカ国","cap.DM":"ロゾー","fam.DM":"ボイリング・レイク（ふっとうする湖）","fact.DM":"ドミニカ国は「自然の島」とよばれていて、川が365本あるといわれているよ。1年の毎日に1本ずつだね。","name.DK":"デンマーク","cap.DK":"コペンハーゲン","fam.DK":"カラフルなレゴブロック","fact.DK":"レゴはデンマークで生まれたよ。名前はデンマーク語の「レッグ・ゴット」からきていて、「よくあそべ」という意味なんだ。","name.DO":"ドミニカ共和国","cap.DO":"サントドミンゴ","fam.DO":"空色の宝石ラリマー","fact.DO":"ドミニカ共和国は、アメリカの次に多くの選手をメジャーリーグに送り出しているんだ。","name.DZ":"アルジェリア","cap.DZ":"アルジェ","fam.DZ":"タッシリ・ナジェールの岩絵","fact.DZ":"アフリカでいちばん大きな国で、国の80パーセント以上がサハラさばくにおおわれているよ。","name.EC":"エクアドル","cap.EC":"キト","fam.EC":"ガラパゴス諸島","fact.EC":"地球は赤道のところがふくらんでいるから、チンボラソ山のてっぺんは、陸の上で地球の中心からいちばん遠い場所なんだ。","name.EG":"エジプト","cap.EG":"カイロ","fam.EG":"ギザのピラミッド","fact.EG":"ギザの大ピラミッドは、約3,800年ものあいだ人がつくった世界一高い建物だったよ。そのあと、イギリスの大聖堂がぬいたんだ。","name.ER":"エリトリア","cap.ER":"アスマラ","fam.ER":"ダフラク諸島","fact.ER":"首都アスマラは、カラフルな古い建物で有名だよ。長いつばさのある飛行機の形をしたガソリンスタンドまであるんだ。","name.ES":"スペイン","cap.ES":"マドリード","fam.ES":"フラメンコとパエリア","fact.ES":"毎年8月、ブニョールの町では「トマティーナ」という大きなお祭りがあって、何千人もの人がトマトをなげあうんだ！","name.EE":"エストニア","cap.EE":"タリン","fam.EE":"スカイプを発明したこと","fact.EE":"エストニアは国のおよそ半分が森で、海岸ぞいには2,000以上の島があるよ。","name.ET":"エチオピア","cap.ET":"アディスアベバ","fam.ET":"コーヒーのふるさと","fact.ET":"エチオピアには13か月ある自分たちのこよみがあるよ。お正月は9月で、年の数は約7年おくれているんだ！","name.FI":"フィンランド","cap.FI":"ヘルシンキ","fam.FI":"ムーミンとサウナ","fact.FI":"フィンランドにはサウナが約300万こもあるよ。だいたい2人に1つあるくらいなんだ！","name.FJ":"フィジー","cap.FJ":"スバ","fam.FJ":"7人制ラグビーのオリンピック金メダル","fact.FJ":"フィジーは330以上の島でできているけど、人がすんでいるのはそのうち約110だけなんだ。","name.FR":"フランス","cap.FR":"パリ","fam.FR":"エッフェル塔","fact.FR":"フランスは世界中に島をもっているから、時間帯が12もあるよ。これはどの国よりも多いんだ！","name.FM":"ミクロネシア連邦","cap.FM":"パリキール","fam.FM":"石の遺跡ナン・マドール","fact.FM":"ヤップ島では、大きな丸い石の円ばんをお金としてつかってきたよ。大人より大きくて、重すぎて動かせないものもあるんだ！","name.GA":"ガボン","cap.GA":"リーブルビル","fam.GA":"波乗りするカバ","fact.GA":"ガボンの海岸では、海の波でバシャバシャするカバや、すなはまを歩くゾウ、沖を泳ぐクジラが見られることがあるんだ！","name.GB":"イギリス","cap.GB":"ロンドン","fam.GB":"時計台のビッグ・ベン","fact.GB":"サッカー、ラグビー、テニス、クリケットは、どれもイギリスで今のルールができたよ。今では世界中であそばれているんだ。","name.GE":"ジョージア","cap.GE":"トビリシ","fam.GE":"チーズパンのハチャプリ","fact.GE":"ジョージアには自分たちの文字があるよ。今もつかわれている中でとても古い文字の1つで、くるくるした33の文字は英語の文字とぜんぜんちがうんだ。","name.GH":"ガーナ","cap.GH":"アクラ","fam.GH":"ケンテという布","fact.GH":"ボルタ湖は、面積でいうと人がつくった湖の中で世界一大きいよ。ボルタ川にダムをつくってできたんだ。","name.GN":"ギニア","cap.GN":"コナクリ","fam.GN":"フータ・ジャロン高地","fact.GN":"ニジェール川、セネガル川、ガンビア川は、どれもギニアの高地から流れ出ているよ。だから「西アフリカの給水塔」とよばれるんだ。","name.GM":"ガンビア","cap.GM":"バンジュール","fam.GM":"「アフリカのほほえみの海岸」","fact.GM":"アフリカ大陸でいちばん小さな国だよ。川にそった細長い国で、3つの方向をセネガルにかこまれているんだ。","name.GW":"ギニアビサウ","cap.GW":"ビサウ","fam.GW":"ビジャゴ諸島","fact.GW":"ビジャゴ諸島には、島から島へしょっぱい海の水の中を泳ぐカバがいるよ。すなはまではアオウミガメがたまごをうむんだ。","name.GQ":"赤道ギニア","cap.GQ":"マラボ","fam.GQ":"ビオコ島","fact.GQ":"アフリカでスペイン語が公用語になっているのはこの国だけ。首都は大陸ではなく島の上にあるんだ。","name.GR":"ギリシャ","cap.GR":"アテネ","fam.GR":"古代オリンピック","fact.GR":"オリンピックは、約2,800年前に古代ギリシャのオリンピアという場所ではじまったんだ。","name.GD":"グレナダ","cap.GD":"セントジョージズ","fam.GD":"ナツメグとスパイス","fact.GD":"グレナダには海の中の彫刻公園があるよ。海のそこの像は、だんだんサンゴや魚のすみかになっていくんだ。","name.GT":"グアテマラ","cap.GT":"グアテマラシティ","fam.GT":"マヤの都市ティカル","fact.GT":"国の鳥はケツァールで、長くてキラキラした緑のおばねをもっているよ。お金の名前もケツァールなんだ！","name.GY":"ガイアナ","cap.GY":"ジョージタウン","fam.GY":"巨大なカイエトゥールの滝","fact.GY":"ガイアナは、南アメリカで英語が公用語になっているただ1つの国なんだ。","name.HN":"ホンジュラス","cap.HN":"テグシガルパ","fam.HN":"マヤのコパン遺跡","fact.HN":"沖にはバイア諸島があって、世界で2番目に大きいサンゴ礁のすぐそばなんだ。ジンベエザメやウミガメがすんでいるよ。","name.HR":"クロアチア","cap.HR":"ザグレブ","fam.HR":"プリトヴィツェ湖群","fact.HR":"『101匹わんちゃん』の黒いぶちもようの犬ダルメシアンは、クロアチアの海ぞいにある、お日さまいっぱいのダルマチア地方から名前がついたんだ。","name.HT":"ハイチ","cap.HT":"ポルトープランス","fam.HT":"シタデル・ラフェリエール（とりで）","fact.HT":"ハイチはカリブ海でもとくに山の多い国だよ。名前はタイノ族のことばで「高い山の土地」という意味なんだ。","name.HU":"ハンガリー","cap.HU":"ブダペスト","fam.HU":"ルービックキューブ","fact.HU":"ルービックキューブは1974年にハンガリーで発明されたよ。首都ブダペストの地下には、100以上の天然の温泉があるんだ。","name.ID":"インドネシア","cap.ID":"ジャカルタ","fam.ID":"大きなコモドドラゴン","fact.ID":"インドネシアは17,000以上の島でできているよ。はしからはしまでは、アメリカ本土よりも長いんだ。","name.IN":"インド","cap.IN":"ニューデリー","fam.IN":"タージ・マハル","fact.IN":"ボリウッドをふくむインドの映画の世界は、毎年どの国よりもたくさんの映画をつくっているんだ。","name.IE":"アイルランド","cap.IE":"ダブリン","fam.IE":"シャムロックとレプラコーン","fact.IE":"ハロウィーンはアイルランドではじまったよ。むかしはカボチャではなく、カブに顔をほってランタンをつくっていたんだ！","name.IR":"イラン","cap.IR":"テヘラン","fam.IR":"美しいペルシャじゅうたん","fact.IR":"むかしイランの人たちは「ヤフチャール」という大きなドームの形の氷の家をつくったよ。さばくでも夏のあいだずっと氷をこおらせておけたんだ。","name.IQ":"イラク","cap.IQ":"バグダッド","fam.IQ":"古代都市バビロン","fact.IQ":"世界でさいしょの文字の1つは、5,000年以上前の古代イラクで生まれたよ。ねん土の板にくさびの形をおしつけて書いたんだ。","name.IS":"アイスランド","cap.IS":"レイキャビク","fam.IS":"間欠泉と火山","fact.IS":"アイスランドには蚊が1ぴきもいないよ。夏はお日さまがほとんどしずまないから、夜もずっと明るいんだ。","name.IL":"イスラエル","cap.IL":"エルサレム","fam.IL":"さばくのとりでマサダ","fact.IL":"イスラエルの東のはしにある死海はとてもしょっぱいから、泳ごうとしなくても水にぷかぷかうかべるんだ。","name.IT":"イタリア","cap.IT":"ローマ","fam.IT":"ピザとピサの斜塔","fact.IT":"イタリアには、古代の遺跡からベネチアの運河まで、世界のどの国よりも多くのユネスコ世界遺産があるんだ。","name.JM":"ジャマイカ","cap.JM":"キングストン","fam.JM":"レゲエ音楽","fact.JM":"ジャマイカからは、世界でもとくに足のはやいランナーが生まれているよ。100メートルの世界記録をもつウサイン・ボルトもその1人なんだ。","name.JO":"ヨルダン","cap.JO":"アンマン","fam.JO":"バラ色の都市ペトラ","fact.JO":"ヨルダンのワディ・ラムさばくは、すなも岩もとても赤いから、火星がぶたいの映画のさつえいにつかわれてきたんだ。","name.JP":"日本","cap.JP":"東京","fam.JP":"おすしと新幹線","fact.JP":"日本には何百万台ものじどうはんばいきがあるよ。つめたい飲み物、あたたかいスープ、アイス、なんとかさまで売っているんだ。","name.KZ":"カザフスタン","cap.KZ":"アスタナ","fam.KZ":"リンゴのふるさと","fact.KZ":"カザフスタンは、海に面していない国の中で世界一大きいよ。西ヨーロッパぜんぶよりも大きいんだ。","name.KE":"ケニア","cap.KE":"ナイロビ","fam.KE":"マサイ・マラ国立保護区","fact.KE":"ケニアのランナーはマラソンで勝つことで有名だよ。国のまん中を赤道が通っていて、北と南に分けているんだ。","name.KG":"キルギス","cap.KG":"ビシュケク","fam.KG":"山の湖イシク・クル","fact.KG":"キルギスの遊牧民は「ユルト」という丸いテントでくらしているよ。ユルトの屋根のてっぺんは、国旗にもえがかれているんだ。","name.KH":"カンボジア","cap.KH":"プノンペン","fam.KH":"アンコール・ワット","fact.KH":"雨の季節になると、カンボジアのトンレサップ湖は何倍もの大きさにふくらんで、湖から流れ出る川の向きが反対になるんだ！","name.KI":"キリバス","cap.KI":"南タラワ","fam.KI":"世界でいちばん早い初日の出","fact.KI":"キリバスは、北半球・南半球・東半球・西半球の4つすべてにある、ただ1つの国だよ。赤道と180度の線の両方をまたいでいるんだ。","name.KN":"セントクリストファー・ネービス","cap.KN":"バセテール","fam.KN":"ブリムストーン・ヒル要塞","fact.KN":"南北アメリカでいちばん小さな国だよ。島には人よりもミドリザルのほうが多いという人もいるんだ！","name.KR":"韓国","cap.KR":"ソウル","fam.KR":"キムチとK-POP","fact.KR":"韓国のインターネットは世界でもトップクラスのはやさだよ。プロのゲーム選手は、スポーツ選手と同じくらい有名になることもあるんだ。","name.KW":"クウェート","cap.KW":"クウェートシティ","fam.KW":"青い玉のついた給水塔","fact.KW":"クウェートには川も湖も1つもないよ。だから、飲み水のほとんどは海水から塩をとりのぞいてつくっているんだ。","name.LA":"ラオス","cap.LA":"ビエンチャン","fam.LA":"ジャール平原（石のつぼ）","fact.LA":"ラオスには海がないけど、メコン川が流れているよ。そこには「4,000の島」という意味のシーパンドンという場所があるんだ。","name.LB":"レバノン","cap.LB":"ベイルート","fam.LB":"古いレバノンスギの木","fact.LB":"レバノンの国旗のまん中には、緑のレバノンスギがえがかれているよ。この木は1,000年以上も生きることがあるんだ！","name.LR":"リベリア","cap.LR":"モンロビア","fam.LR":"サポ国立公園","fact.LR":"リベリアの国旗はアメリカの国旗によくにているけど、星は50こではなく、大きな白い星が1つだけなんだ。","name.LY":"リビア","cap.LY":"トリポリ","fam.LY":"レプティス・マグナの遺跡","fact.LY":"国の90パーセント以上がさばくだよ。「大人工河川」という地下の大きなパイプで、町まで水を運んでいるんだ。","name.LC":"セントルシア","cap.LC":"カストリーズ","fam.LC":"2つならんだピトン山","fact.LC":"セントルシアのスフリエールの近くには、車で行ける火山があるよ。ブクブクわくどろの池や温泉のすぐそばまで行けるんだ。","name.LI":"リヒテンシュタイン","cap.LI":"ファドゥーツ","fam.LI":"入れ歯づくり","fact.LI":"この小さな国は、世界に2つしかない「二重内陸国」の1つ。となりの国もぜんぶ海に面していないんだ！","name.LK":"スリランカ","cap.LK":"コロンボ","fam.LK":"有名なセイロンティー","fact.LK":"なみだのしずくの形をしたこの島には首都が2つあるよ。にぎやかなコロンボと、そのとなりで国会がひらかれるスリジャヤワルダナプラコッテなんだ。","name.LS":"レソト","cap.LS":"マセル","fam.LS":"「天空の王国」とよばれること","fact.LS":"国の土地がぜんぶ海面から1,000メートルより高いところにある、世界でただ1つの国だよ。だから「天空の王国」とよばれるんだ。","name.LT":"リトアニア","cap.LT":"ビリニュス","fam.LT":"十字架の丘","fact.LT":"リトアニアのバスケットボールチームはオリンピックで銅メダルを3回とっていて、国中でとても人気があるんだ。","name.LU":"ルクセンブルク","cap.LU":"ルクセンブルク","fam.LU":"世界でただ1つの大公国","fact.LU":"2020年、ルクセンブルクは世界ではじめて、バスも路面電車も電車もみんなただで乗れる国になったんだ。","name.LV":"ラトビア","cap.LV":"リガ","fam.LV":"ガウヤ国立公園","fact.LV":"ラトビアはヨーロッパでもとくに緑の多い国だよ。国の半分以上が森におおわれているんだ。","name.MA":"モロッコ","cap.MA":"ラバト","fam.MA":"青い町シャウエン","fact.MA":"フェズにある859年にできたカラウィーイーン大学は、今もつづく世界でいちばん古い大学といわれることが多いんだ。","name.MC":"モナコ","cap.MC":"モナコ","fam.MC":"町の中を走るF1レース","fact.MC":"モナコは世界で2番目に小さい国だよ。とても小さいから、1時間もかからずに歩いてよこぎれるんだ。","name.MD":"モルドバ","cap.MD":"キシナウ","fam.MD":"大きな地下のワインぐら","fact.MD":"モルドバのミレシュティ・ミチにある地下のワインぐらは、トンネルの長さが約200キロメートルもあるよ。だから見学する人は車で中を走るんだ！","name.MG":"マダガスカル","cap.MG":"アンタナナリボ","fam.MG":"キツネザル","fact.MG":"マダガスカルの植物や動物の約90パーセントは、地球のほかの場所にはいないよ。キツネザルだけでも100種類以上いるんだ！","name.MV":"モルディブ","cap.MV":"マレ","fam.MV":"地球でいちばんひくい国","fact.MV":"モルディブは約1,200のサンゴの島でできているよ。国でいちばん高い自然の場所でも、高さは約2.4メートルしかないんだ。","name.MX":"メキシコ","cap.MX":"メキシコシティ","fam.MX":"チチェン・イッツァのピラミッド","fact.MX":"トウモロコシは約9,000年前にメキシコではじめてそだてられたよ。今ではトルティーヤやタマルなど、いろいろな料理で食べられているんだ。","name.MH":"マーシャル諸島","cap.MH":"マジュロ","fam.MH":"航海のためのぼうの海図","fact.MH":"この国は29のサンゴの環礁と5つの島でできているよ。土地のほとんどは、海面からたった2メートルくらいの高さなんだ。","name.MK":"北マケドニア","cap.MK":"スコピエ","fam.MK":"オフリドの旧市街","fact.MK":"オフリド湖は100万年以上前からある、世界でもとくに古い湖だよ。ほかではみられない生き物がたくさんすんでいるんだ。","name.ML":"マリ","cap.ML":"バマコ","fam.ML":"古い都市トンブクトゥ","fact.ML":"ジェンネの大モスクは、どろのレンガでできた建物として世界一大きいよ。毎年みんなで新しいどろをぬりなおすんだ。","name.MT":"マルタ","cap.MT":"バレッタ","fam.MT":"ジュガンティーヤ神殿","fact.MT":"マルタのジュガンティーヤ神殿は5,000年以上前のもので、ストーンヘンジやエジプトのピラミッドよりも古いんだ！","name.MM":"ミャンマー","cap.MM":"ネピドー","fam.MM":"バガンの寺院","fact.MM":"ミャンマーでは、多くの人が「タナカ」という黄色いクリームを顔にぬっているよ。木の皮をすりつぶしてつくっていて、日ざしの中でもすずしくすごせるんだ。","name.ME":"モンテネグロ","cap.ME":"ポドゴリツァ","fam.ME":"コトル湾","fact.ME":"モンテネグロという名前は「黒い山」という意味だよ。海の近くのロヴチェン山をおおう、くらい森からついたんだ。","name.MN":"モンゴル","cap.MN":"ウランバートル","fam.MN":"大きなチンギス・ハーン像","fact.MN":"モンゴルには人よりも馬のほうがたくさんいるよ。夏の大きなお祭り「ナーダム」では、子どもたちが草原で馬のレースをするんだ。","name.MZ":"モザンビーク","cap.MZ":"マプト","fam.MZ":"バザルト諸島","fact.MZ":"バザルト諸島のまわりでは、やさしい「海の牛」ジュゴンが今も泳いでいるよ。イルカやウミガメ、大きなジンベエザメもいるんだ。","name.MR":"モーリタニア","cap.MR":"ヌアクショット","fam.MR":"サハラの目","fact.MR":"「サハラの目」ははばが約40キロメートルもある大きな岩の輪だよ。とても大きいから、宇宙飛行士が宇宙から目じるしにしているんだ！","name.MU":"モーリシャス","cap.MU":"ポートルイス","fam.MU":"鳥のドードー","fact.MU":"ドードーは空を飛べない大きな鳥で、この島にだけすんでいたよ。今では国の紋章にえがかれているんだ。","name.MW":"マラウイ","cap.MW":"リロングウェ","fam.MW":"「アフリカのあたたかい心」","fact.MW":"マラウイ湖には、世界のどの湖よりも多くの種類の魚がいるよ。その多くは、あざやかな色のシクリッドなんだ。","name.MY":"マレーシア","cap.MY":"クアラルンプール","fam.MY":"ペトロナス・ツインタワー","fact.MY":"マレーシアの熱帯雨林には、世界一大きな花ラフレシアがさくよ。車のタイヤくらい大きくなって、くさった肉みたいなにおいがするんだ！","name.NA":"ナミビア","cap.NA":"ウィントフック","fam.NA":"ソススフレイの赤いすな丘","fact.NA":"世界でもとくに高いすな丘がナミブさばくにあるよ。ナミブは地球でいちばん古いさばくだと考えられているんだ。","name.NE":"ニジェール","cap.NE":"ニアメ","fam.NE":"コウレのキリン","fact.NE":"ニジェールには、野生で生きのこっている最後のニシアフリカキリンがすんでいるよ。首都からそう遠くない村や畑の近くを自由に歩いているんだ。","name.NG":"ナイジェリア","cap.NG":"アブジャ","fam.NG":"ノリウッド映画","fact.NG":"ナイジェリアはアフリカでいちばん人口が多い国だよ。映画の世界「ノリウッド」では、毎年何千本もの映画がつくられているんだ。","name.NI":"ニカラグア","cap.NI":"マナグア","fam.NI":"オメテペ島のふたごの火山","fact.NI":"ニカラグア湖はとても大きくて、何百もの島があるよ。オオメジロザメが川をさかのぼって、海から湖に入ってくるんだ！","name.NL":"オランダ","cap.NL":"アムステルダム","fam.NL":"風車とチューリップ","fact.NL":"オランダの約4分の1は海面よりひくい土地だよ。ていぼうやポンプ、そしてむかしは風車で、水が入らないようにしてきたんだ。","name.NO":"ノルウェー","cap.NO":"オスロ","fam.NO":"深いフィヨルド","fact.NO":"日本でサーモンのおすしが人気になったのは、ノルウェーのおかげなんだ。1980年代に、ノルウェーが日本へサーモンを送りはじめたんだよ。","name.NP":"ネパール","cap.NP":"カトマンズ","fam.NP":"ゆうかんなシェルパの山ガイド","fact.NP":"ネパールの国旗は、世界でただ1つ四角形じゃない国旗だよ。三角形を2つかさねた形をしているんだ。","name.NR":"ナウル","cap.NR":"ヤレン","fam.NR":"とても小さな島国","fact.NR":"ナウルはとても小さくて、島をぐるっと1周する道は約19キロメートルしかないよ。車なら約30分で1周できるんだ。","name.NZ":"ニュージーランド","cap.NZ":"ウェリントン","fam.NZ":"鳥のキーウィ","fact.NZ":"ニュージーランドにはもともと陸にすむヘビがいないよ。そして、地球の大きな土地の中で、人がすむようになったのがとくにおそい場所の1つなんだ。","name.OM":"オマーン","cap.OM":"マスカット","fam.OM":"乳香の木","fact.OM":"オマーンには、青緑色の水がたまったビマー・シンクホールという大きな穴があるよ。泳いでいると、小さな魚が足をやさしくつっついてくるんだ。","name.PK":"パキスタン","cap.PK":"イスラマバード","fam.PK":"ピンク色のヒマラヤ岩塩","fact.PK":"世界に14ある8,000メートルより高い山のうち、5つがパキスタンにあるよ。地球で2番目に高いK2もその1つなんだ。","name.PA":"パナマ","cap.PA":"パナマシティ","fam.PA":"2つの海をつなぐ運河","fact.PA":"パナマ運河を通る船は、大きな「こうもん」で約26メートルも持ち上げられるよ。水でできたエレベーターみたいだね。","name.PE":"ペルー","cap.PE":"リマ","fam.PE":"マチュピチュの遺跡","fact.PE":"ペルーでは3,000種類以上のジャガイモがそだてられているよ。ジャガイモは何千年も前に、アンデス山脈ではじめて畑でつくられたんだ。","name.PH":"フィリピン","cap.PH":"マニラ","fam.PH":"チョコレート・ヒルズ","fact.PH":"フィリピンには、ものすごく大きな目をした小さな動物、メガネザルがいるよ。目1つが、のうみそ全体と同じくらいの大きさなんだ！","name.PW":"パラオ","cap.PW":"ンゲルルムド","fam.PW":"ジェリーフィッシュレイクでの泳ぎ","fact.PW":"パラオに来た人のパスポートには、島の自然と海の生き物を守るという「やくそく」のスタンプがおされるんだ。","name.PG":"パプアニューギニア","cap.PG":"ポートモレスビー","fam.PG":"ゴクラクチョウ","fact.PG":"パプアニューギニアでは800以上のことばが話されているよ。これは世界のどの国よりも多いんだ。","name.PL":"ポーランド","cap.PL":"ワルシャワ","fam.PL":"ギョーザみたいなピエロギ","fact.PL":"女性ではじめてノーベル賞をとったマリー・キュリーは、1867年にポーランドのワルシャワで生まれたんだ。","name.KP":"北朝鮮","cap.KP":"ピョンヤン","fam.KP":"ピラミッドの形の大きなホテル","fact.KP":"朝鮮半島でいちばん高い白頭山は、むかしの火山だよ。てっぺんには「天池」という火口湖があるんだ。","name.PT":"ポルトガル","cap.PT":"リスボン","fam.PT":"エッグタルトのパステル・デ・ナタ","fact.PT":"ポルトガルは世界のコルクの約半分をつくっているよ。コルクはコルクガシの木の皮で、びんのせんやボードにつかわれるんだ。","name.PY":"パラグアイ","cap.PY":"アスンシオン","fam.PY":"クモの巣みたいなニャンドゥティ・レース","fact.PY":"パラグアイでは、多くの人がスペイン語と、南アメリカに古くからあるグアラニー語を話すよ。どちらも公用語なんだ。","name.PS":"パレスチナ","cap.PS":"ラマッラ","fam.PS":"古い町エリコ","fact.PS":"エリコは世界でもとくに古い町の1つだよ。1万年以上も前から人がすんでいて、海面よりずっとひくいところにあるんだ。","name.QA":"カタール","cap.QA":"ドーハ","fam.QA":"2022年のサッカーワールドカップ","fact.QA":"カタールには「ホール・アル・ウダイド」という内海があって、大きなすな丘が水ぎわまでつづいているんだ。","name.RO":"ルーマニア","cap.RO":"ブカレスト","fam.RO":"トランシルバニアのお城","fact.RO":"ルーマニアのカルパティア山脈には、ロシアをのぞくヨーロッパのどの国よりも多くのヒグマがすんでいるんだ。","name.RU":"ロシア","cap.RU":"モスクワ","fam.RU":"マトリョーシカ人形","fact.RU":"ロシアはとても広いので、時間帯が11もあるよ。そしてバイカル湖は地球でいちばん深い湖なんだ。","name.RW":"ルワンダ","cap.RW":"キガリ","fam.RW":"「千の丘の国」","fact.RW":"ルワンダではビニールぶくろがきんしされているよ。毎月1回の土曜日には、みんなでいっしょに町をそうじするから、道がいつもきれいなんだ。","name.SA":"サウジアラビア","cap.SA":"リヤド","fam.SA":"ルブアルハリさばく","fact.SA":"サウジアラビアは、いつも流れている川がない国の中でとても大きな国だよ。だから海水からたくさんの真水をつくっているんだ。","name.SD":"スーダン","cap.SD":"ハルツーム","fam.SD":"エジプトよりたくさんのピラミッド","fact.SD":"スーダンにはエジプトよりも多い、約200の古代のピラミッドがあるよ。むかしのクシュの王さまや女王さまがつくったんだ。","name.SN":"セネガル","cap.SN":"ダカール","fam.SN":"ピンクの湖ラック・ローズ","fact.SN":"ラック・ローズは、とてもしょっぱい水の中の小さな藻のおかげで、あざやかなピンク色に見えるよ。人びとは湖のそこから手で塩をあつめているんだ。","name.SG":"シンガポール","cap.SG":"シンガポール","fam.SG":"マーライオン像","fact.SG":"シンガポールは「都市国家」で、国ぜんたいが1つの町なんだ。海ぞいに新しい土地をつくって、国を広げてきたよ。","name.SB":"ソロモン諸島","cap.SB":"ホニアラ","fam.SB":"大きなマロボ・ラグーン","fact.SB":"ここではむかしから、小さな貝のビーズをつないだものをお金としてつかう人たちがいるよ。今でもとくべつな行事で貝のお金がつかわれるんだ。","name.SL":"シエラレオネ","cap.SL":"フリータウン","fam.SL":"タクガマのチンパンジー保護区","fact.SL":"ティワイ島には、コビトカバと、チンパンジーやコロブスなど11種類のサルのなかまがすんでいるよ。","name.SV":"エルサルバドル","cap.SV":"サンサルバドル","fam.SV":"トウモロコシのおやきププサ","fact.SV":"エルサルバドルは中央アメリカでいちばん小さい国だけど、火山が20以上もあるから「火山の国」とよばれているんだ。","name.SM":"サンマリノ","cap.SM":"サンマリノ","fam.SM":"ティターノ山の3つの塔","fact.SM":"サンマリノは世界でもとくに古い共和国の1つだよ。なんと301年にできたといわれているんだ。","name.SO":"ソマリア","cap.SO":"モガディシュ","fam.SO":"アフリカ大陸でいちばん長い海岸","fact.SO":"ソマリアはアフリカ大陸の国の中でいちばん長い海岸線をもっているよ。ぼくちくをする人たちは、ミルクのために何百万頭ものラクダをかっているんだ。","name.RS":"セルビア","cap.RS":"ベオグラード","fam.RS":"山ほどのラズベリー","fact.RS":"セルビアではとてもたくさんのラズベリーがそだてられていて、世界でもトップクラスのラズベリーの産地なんだ。","name.SS":"南スーダン","cap.SS":"ジュバ","fam.SS":"大きなぬま地スッド","fact.SS":"スッドは世界でもとくに大きなぬま地だよ。毎年、シロミミコーブというレイヨウの大きなむれが、この土地を旅していくんだ。","name.ST":"サントメ・プリンシペ","cap.ST":"サントメ","fam.ST":"とがった岩山ピコ・カン・グランデ","fact.ST":"ここにある小さなロラス島を赤道が通っているよ。島には北と南のさかいめをしめす目じるしがあるんだ。","name.SR":"スリナム","cap.SR":"パラマリボ","fam.SR":"オランダ語を話すアマゾン","fact.SR":"スリナムは国の約90%が熱帯雨林におおわれていて、地球でもとくに緑と森の多い国なんだ。","name.SK":"スロバキア","cap.SK":"ブラチスラバ","fam.SK":"大きなスピシュ城","fact.SK":"スロバキアは、人口1人あたりでつくる車の数が世界でいちばん多い国なんだ！","name.SI":"スロベニア","cap.SI":"リュブリャナ","fam.SI":"ブレッド湖にうかぶ島","fact.SI":"スロベニアのポストイナ洞くつには、ホライモリという目の見えないピンク色のサンショウウオがすんでいるよ。100年以上生きることもあるんだ！","name.SE":"スウェーデン","cap.SE":"ストックホルム","fam.SE":"組み立て家具とABBA","fact.SE":"スウェーデンには、近くのトーネ川からとった雪と氷で、毎年冬につくりなおすアイスホテルがあるんだ。","name.SZ":"エスワティニ","cap.SZ":"ムババーネ","fam.SZ":"ウムランガ（リード・ダンス）","fact.SZ":"ムババーネは政府のある町で、ロバンバは王さまの首都だよ。毎年のリード・ダンスでは、何千人もの女の子が背の高いアシをかかげて運ぶんだ。","name.SC":"セーシェル","cap.SC":"ビクトリア","fam.SC":"大きなココ・デ・メールの実","fact.SC":"ココ・デ・メールというヤシは、地球の植物の中でいちばん大きなたねをつけるよ。1つで25キログラムにもなるんだ！","name.SY":"シリア","cap.SY":"ダマスカス","fam.SY":"クラック・デ・シュヴァリエ城","fact.SY":"シリアで有名なアレッポのせっけんは、オリーブ油とローレル油からつくられるよ。何百年も前からつくられているんだ。","name.TD":"チャド","cap.TD":"ンジャメナ","fam.TD":"エネディの岩のアーチ","fact.TD":"エネディさばくには大きな自然の岩のアーチがあるよ。かくれた池には、めずらしいさばくのワニが今もすんでいるんだ。","name.TG":"トーゴ","cap.TG":"ロメ","fam.TG":"クタマクのどろの家","fact.TG":"クタマクでは、小さなお城みたいな背の高いどろの家をつくるよ。上の塔には穀物をしまっておくんだ。","name.TH":"タイ","cap.TH":"バンコク","fam.TH":"トゥクトゥクと水上マーケット","fact.TH":"タイには、地球でもとくに小さいほにゅう類のキティブタバナコウモリがいるよ。重さはゼムクリップ1つくらいなんだ。","name.TJ":"タジキスタン","cap.TJ":"ドゥシャンベ","fam.TJ":"高いパミール高原","fact.TJ":"タジキスタンは国の90パーセント以上が山で、国のおよそ半分は3,000メートルより高いところにあるんだ。","name.TM":"トルクメニスタン","cap.TM":"アシガバート","fam.TM":"もえつづけるダルヴァザの穴","fact.TM":"トルクメニスタンのアハルテケという馬は、毛がみがいた金属みたいにピカピカ光るから、「黄金の馬」とよばれることが多いんだ。","name.TL":"東ティモール","cap.TL":"ディリ","fam.TL":"アタウロ島のサンゴ礁","fact.TL":"「ティモール」はマレー語で「東」、「レステ」はポルトガル語で「東」という意味。だから国の名前は「東・東」なんだ！","name.TO":"トンガ","cap.TO":"ヌクアロファ","fam.TO":"ハアモンガの石のアーチ","fact.TO":"ザトウクジラは毎年、何千キロメートルも旅をして、トンガのあたたかい海に赤ちゃんをうみにくるんだ。","name.TT":"トリニダード・トバゴ","cap.TT":"ポートオブスペイン","fam.TT":"スチールパンのたいこ","fact.TT":"トリニダード島のピッチ湖は、世界でいちばん大きな天然のアスファルトの湖だよ。ところによっては上を歩くこともできるんだ。","name.TN":"チュニジア","cap.TN":"チュニス","fam.TN":"スター・ウォーズのさばくのセット","fact.TN":"スター・ウォーズの一部はここでさつえいされたよ。ルーク・スカイウォーカーのふるさとの星タトゥイーンの名前は、タタウィンという町からきているんだ。","name.TR":"トルコ","cap.TR":"アンカラ","fam.TR":"カッパドキアの岩","fact.TR":"トルコでいちばん大きな町イスタンブールは、ヨーロッパとアジアの2つの大陸にまたがっているよ。そのあいだには海峡があるんだ。","name.TV":"ツバル","cap.TV":"フナフティ","fam.TV":"インターネットの「.tv」アドレス","fact.TV":"ツバルは地球でもとくに小さな国の1つで、いちばん高い場所でも海面から約4.6メートルしかないんだ。","name.TZ":"タンザニア","cap.TZ":"ドドマ","fam.TZ":"キリマンジャロ山","fact.TZ":"キリマンジャロ山は高さ5,895メートルで、アフリカでいちばん高い山だよ。ほかの山とつながらずにぽつんと立つ山としては、世界一高いんだ。","name.UG":"ウガンダ","cap.UG":"カンパラ","fam.UG":"ジンジャにあるナイル川のみなもと","fact.UG":"アフリカでいちばん大きな湖、ビクトリア湖から白ナイル川がはじまるよ。そこから北の地中海まで、長い旅をするんだ。","name.UA":"ウクライナ","cap.UA":"キーウ","fam.UA":"金色のひまわり畑","fact.UA":"キーウのアルセナーリナ駅は、世界でもとくに深い地下鉄の駅の1つ。地下約105メートルにあるんだ。","name.UY":"ウルグアイ","cap.UY":"モンテビデオ","fam.UY":"はまべの大きな手のオブジェ","fact.UY":"ウルグアイは1930年、自分の国でひらいたさいしょのサッカーワールドカップで、決勝でアルゼンチンに勝って優勝したんだ。","name.US":"アメリカ","cap.US":"ワシントンD.C.","fam.US":"自由の女神","fact.US":"1872年にできたイエローストーンは世界ではじめての国立公園だよ。熱いお湯をふき上げる間欠泉が500以上あるんだ。","name.UZ":"ウズベキスタン","cap.UZ":"タシケント","fam.UZ":"サマルカンドの青いドーム","fact.UZ":"ウズベキスタンは、世界に2つしかない「二重内陸国」の1つだよ。海に出るには、少なくとも2つの国をこえないといけないんだ。","name.VA":"バチカン","cap.VA":"バチカン","fam.VA":"システィーナ礼拝堂","fact.VA":"バチカンは世界でいちばん小さな国だよ。とても小さくて、ローマの町の中にすっぽり入っているんだ！","name.VC":"セントビンセント・グレナディーン","cap.VC":"キングスタウン","fam.VC":"ワリラボの海ぞくの映画セット","fact.VC":"セントビンセントボウシインコは、地球でここにしかいないカラフルな大きな鳥で、この島々の国の鳥なんだ。","name.VE":"ベネズエラ","cap.VE":"カラカス","fam.VE":"世界一高い滝","fact.VE":"マラカイボ湖の上では、1年に約260日の夜、音のないいなずまが空でピカピカ光るよ。地球でもトップクラスの多さなんだ。","name.VN":"ベトナム","cap.VN":"ハノイ","fam.VN":"ハロン湾の島々","fact.VN":"ベトナムのソンドン洞くつは世界一大きな洞くつだよ。とても大きくて、中に川やジャングル、雲まであるんだ！","name.VU":"バヌアツ","cap.VU":"ポートビラ","fam.VU":"高いやぐらからとびおりるランド・ダイビング","fact.VU":"バヌアツには海の中の郵便局があるよ。ダイバーは、水にぬれてもだいじょうぶなはがきを海の中から出せるんだ。","name.WS":"サモア","cap.WS":"アピア","fam.WS":"トスア・オーシャン・トレンチ","fact.WS":"サモアは2011年、日付変更線をこえて、12月30日をまるごと1日とばしたよ。オーストラリアとカレンダーを合わせるためなんだ。","name.YE":"イエメン","cap.YE":"サヌア","fam.YE":"竜血樹（りゅうけつじゅ）","fact.YE":"イエメンの古い町シバームには、どろのレンガでできた高い塔のような家がたくさんあるよ。だから「さばくのマンハッタン」とよばれているんだ。","name.ZA":"南アフリカ","cap.ZA":"プレトリア","fam.ZA":"テーブルマウンテン","fact.ZA":"南アフリカには首都が3つあるよ。政府のあるプレトリア、国会のあるケープタウン、そして最高裁判所のあるブルームフォンテーンなんだ。","name.ZM":"ザンビア","cap.ZM":"ルサカ","fam.ZM":"カサンカのコウモリの大移動","fact.ZM":"毎年、約1,000万びきのフルーツコウモリがカサンカ国立公園に飛んでくるよ。地球でいちばん大きなほにゅう類の大移動なんだ！","name.ZW":"ジンバブエ","cap.ZW":"ハラレ","fam.ZW":"ワンゲの大きなゾウのむれ","fact.ZW":"ビクトリアの滝は、地元では「とどろく煙」とよばれているよ。しぶきが何キロメートルもはなれたところから見えるからなんだ。","Hint":"ヒント","Two wrong answers are gone!":"まちがいの答えが2つ消えたよ！","It is in {region}.":"{region}にあるよ。","It is an island country, in {region}.":"{region}にある島の国だよ。","It is next to {name}.":"{name}のとなりだよ。","It is inside the yellow circle!":"黄色い円の中にあるよ！","Culture finds":"文化のはっけん","Press Quiz me to discover more about {name}!":"クイズをおして、{name}のことをもっとはっけんしよう！","Culture finds: {n} of {all}":"文化のはっけん：{all}こ中{n}こ","Every time you get a country right, our paper plane flies there and paints it with its flag. Get it right 3 times and it lights up in full colour!":"国をあてるたびに、紙ひこうきがそこへとんで、その国を国旗のもようでぬってくれるよ。3回あてると、ぜんぶの色でかがやくんだ！","Pick a game below, or tap any country on the globe to open its file and discover its culture. Ready for take-off?":"下からゲームをえらんでね。地球の国をタップすると、その国のファイルがひらいて文化をはっけんできるよ。しゅっぱつのじゅんびはいい？","Food":"食べもの","Celebrations":"おまつり","Arts":"げいじゅつ","Words":"ことば","Nature":"しぜん","Everyday life":"くらし","Culture quest":"文化クエスト","Food, festivals, music and more":"食べもの、おまつり、音楽など","Not quite! The answer is {answer}.":"おしい！こたえは「{answer}」だよ。"},"trivia":{}};
